1	import {
2	  EXTERNAL_TASK_STATUS_LABELS,
3	  type ExternalTask,
4	  type ExternalTaskMeta,
5	} from '../../src/types/task';
6	import type { Conversation, ReminderItem } from '../../src/types/conversation';
7	import type { AgentOrigin } from '../../src/types/agentOrigin';
8	import { root } from '../config';
9	import { resolveAgentOrigin } from '../lib/agentOrigin';
10	import { saveConversation, saveFailureReason } from './conversationStore';
11	import { subscribe, type WorkstationEvent } from './eventBus';
12	import { checkConversationWrite } from './identityGuard';
13	import { sendSystemPush } from './pushNotifier';
14	import {
15	  REMINDERS_ID,
16	  REMINDERS_SLUG,
17	  buildReminderItem,
18	  listPendingReminders,
19	  loadOrInitRemindersConversation,
20	} from './reminderStore';
21	import { findTask, listTasks } from './taskStore';
22	
23	/**
24	 * Failure alerting for Operations › Daemons & jobs — "a job never fails
25	 * silently again, without having to open the Operations page".
26	 *
27	 * When a supervised launchd task (see taskManager.checkTaskHealth) goes into a
28	 * degraded state (`health.healthy === false`: failed run, late run, daemon
29	 * down/not loaded), ONE alert is raised:
30	 *   1. a `high`-priority reminder in the evergreen `_reminders/rappels`
31	 *      conversation (visible at the top of the dashboard and in the bell);
32	 *   2. a Web Push (inert without VAPID keys), sent ONLY when that reminder is
33	 *      newly created.
34	 *
35	 * Dedup — at most ONE PENDING alert reminder per task:
36	 *   - alert reminders carry a parseable id `reminder-taskalert-<taskId>-<t36>-<rand6>`;
37	 *   - while one is pending for a task, no other is created (checked on a FRESH
38	 *     read of the reminders conversation, inside the write retry loop);
39	 *   - in memory, a task already alerted for its current degraded "episode" is
40	 *     not re-alerted even if the user marks the reminder done while the job is
41	 *     still failing; the episode ends when the task is observed healthy again.
42	 *     A recovery never auto-closes the reminder (the user must see it).
43	 *
44	 * Freshness: only health computed AFTER this alerter started is trusted
45	 * (`health.lastCheckedAt >= startedAt`) — a persisted health from before a
46	 * restart may be stale. So at boot nothing fires until the first health-loop
47	 * tick; then a task that failed while the server was down and has no pending
48	 * alert IS alerted, while one that already has a pending alert is not.
49	 *
50	 * Triggers: `task-healthcheck` bus events (immediate), plus a periodic sweep
51	 * (default 60 s) — the health loop does NOT publish on the very first check of
52	 * a task (unknown → unhealthy), and its scheduled-job event payload reports
53	 * `ok: !late` (a failed-but-on-time run publishes ok:true), so the alerter
54	 * never trusts the event payload: it re-reads the task from the store.
55	 * `task-status` is not used — a failed launchctl action is followed by a
56	 * health check, which is what decides.
57	 *
58	 * All writes are serialized through one in-process queue (several tasks can
59	 * transition in the same tick).
60	 */
61	
62	/* -------------------------------------------------------------------------- */
63	/*  Constants                                                                 */
64	/* -------------------------------------------------------------------------- */
65	
66	/** Dashboard location of the Daemons & jobs panel (Operations = /pilotage,
67	 *  DevOps tab, section 00). The front syncs `?tab=` on navigation. */
68	export const TASK_ALERT_HREF = '/pilotage?tab=devops';
69	
70	const ALERT_ID_PREFIX = 'reminder-taskalert-';
71	const ALERT_ID_RE = /^reminder-taskalert-(.+)-([a-z0-9]+)-([a-z0-9]{6})$/;
72	const WRITE_MAX_ATTEMPTS = 3;
73	const DEFAULT_SWEEP_MS = 60_000;
74	
75	/* -------------------------------------------------------------------------- */
76	/*  Pure helpers                                                              */
77	/* -------------------------------------------------------------------------- */
78	
79	export function newAlertItemId(taskId: string): string {
80	  const rand = Math.random().toString(36).slice(2, 8).padEnd(6, '0');
81	  return `${ALERT_ID_PREFIX}${taskId}-${Date.now().toString(36)}-${rand}`;
82	}
83	
84	/** Task id carried by an alert reminder id, or null for any other reminder. */
85	export function taskIdFromAlertItemId(itemId: string): string | null {
86	  const m = ALERT_ID_RE.exec(itemId);
87	  return m ? m[1] : null;
88	}
89	
90	/** The single "degraded" predicate shared by the alerter and the bell. */
91	export function isTaskDegraded(task: Pick<ExternalTask, 'health'>): boolean {
92	  return task.health.healthy === false;
93	}
94	
95	function healthMessage(task: Pick<ExternalTask, 'health' | 'status'>): string {
96	  return task.health.message || EXTERNAL_TASK_STATUS_LABELS[task.status];
97	}
98	
99	export function alertReminderText(task: Pick<ExternalTask, 'title' | 'health' | 'status'>): string {
100	  return `Job en échec : ${task.title} — ${healthMessage(task)} (Operations › Daemons & jobs)`;
101	}
102	
103	/**
104	 * Origin of a reminder written by the server itself. There is no 'system'
105	 * source in the Origin enum: `source: 'http'` is what the other server-side
106	 * background writers already use (boussoleBridge poller, htmlshare ingest) —
107	 * the record is written by the API process. The env is deliberately EMPTY so
108	 * a dev server launched from inside a Claude/Codex session never attributes
109	 * the alert to that session: runtime 'unknown', capturedBy 'none'.
110	 */
111	function systemOrigin(): AgentOrigin {
112	  return resolveAgentOrigin({ env: {}, cwd: root(), source: 'http' });
113	}
114	
115	function pendingAlertTaskIds(conversation: Conversation): Set<string> {
116	  const ids = new Set<string>();
117	  for (const item of conversation.items) {
118	    if (item.kind !== 'reminder' || item.status !== 'pending') continue;
119	    const taskId = taskIdFromAlertItemId(item.id);
120	    if (taskId) ids.add(taskId);
121	  }
122	  return ids;
123	}
124	
125	/** taskId → id of its pending alert reminder (bell episode identity). */
126	async function pendingAlertsByTask(): Promise<Map<string, string>> {
127	  const map = new Map<string, string>();
128	  for (const item of await listPendingReminders()) {
129	    const taskId = taskIdFromAlertItemId(item.id);
130	    if (taskId && !map.has(taskId)) map.set(taskId, item.id);
131	  }
132	  return map;
133	}
134	
135	/* -------------------------------------------------------------------------- */
136	/*  Reminder write                                                            */
137	/* -------------------------------------------------------------------------- */
138	
139	/**
140	 * Append one high-priority alert reminder for `task`, unless one is already
141	 * pending for it. Bounded optimistic-lock retry, same idiom as the
142	 * `remind_add` MCP tool (fresh read → append → save → verify the item
143	 * survived → retry on conflict). Returns the created item, or null when a
144	 * pending alert already existed.
145	 */
146	async function createAlertReminder(task: ExternalTask): Promise<ReminderItem | null> {
147	  let lastReason: string | undefined;
148	  for (let attempt = 1; attempt <= WRITE_MAX_ATTEMPTS; attempt++) {
149	    const conversation = await loadOrInitRemindersConversation('http');
150	    if (pendingAlertTaskIds(conversation).has(task.id)) return null;
151	
152	    const built = buildReminderItem(
153	      {
154	        text: alertReminderText(task),
155	        context:
156	          `Alerte automatique de la workstation : le job launchd ${task.launchdLabel} ` +
157	          `(projet ${task.project.name}) est passé en échec. Détails et logs : ` +
158	          `Operations › Daemons & jobs (${TASK_ALERT_HREF}). Marquer ce rappel fait une fois traité ; ` +
159	          'une nouvelle alerte ne sera levée que lors d’un prochain échec.',
160	      },
161	      systemOrigin(),
162	    );
163	    const item: ReminderItem = { ...built, id: newAlertItemId(task.id), priority: 'high' };
164	
165	    const guard = checkConversationWrite({ items: [item] }, 'claude');
166	    if (!guard.allowed) throw new Error(guard.reason);
167	
168	    const next: Conversation = { ...conversation, items: [...conversation.items, item] };
169	    const result = await saveConversation(REMINDERS_SLUG, REMINDERS_ID, next);
170	    if (result.ok) {
171	      if (result.conversation.items.some((it) => it.id === item.id)) return item;
172	      lastReason = 'item non retrouvé après écriture';
173	      continue;
174	    }
175	    if ('conflict' in result && result.conflict) {
176	      lastReason = saveFailureReason(result);
177	      continue;
178	    }
179	    throw new Error(`store a rejeté l’écriture: ${saveFailureReason(result)}`);
180	  }
181	  throw new Error(
182	    `taskAlerter: échec après ${WRITE_MAX_ATTEMPTS} tentatives — ${lastReason ?? 'raison inconnue'}`,
183	  );
184	}
185	
186	/* -------------------------------------------------------------------------- */
187	/*  Alerter state + evaluation                                                */
188	/* -------------------------------------------------------------------------- */
189	
190	let startedAtMs = 0;
191	let active = false;
192	/** Task ids already alerted (or found with a pending alert) for their current
193	 *  degraded episode. Cleared per task when it is observed healthy again. */
194	const alertedEpisodes = new Set<string>();
195	let queue: Promise<void> = Promise.resolve();
196	
197	function enqueue(fn: () => Promise<void>): Promise<void> {
198	  queue = queue.then(fn).catch((err) => {
199	    // eslint-disable-next-line no-console
200	    console.warn('[taskAlerter] évaluation échouée (non-fatal):', String(err));
201	  });
202	  return queue;
203	}
204	
205	function isFresh(task: ExternalTask): boolean {
206	  const checked = task.health.lastCheckedAt ? Date.parse(task.health.lastCheckedAt) : NaN;
207	  return !Number.isNaN(checked) && checked >= startedAtMs;
208	}
209	
210	async function evaluateTask(id: string): Promise<void> {
211	  if (!active) return;
212	  const task = await findTask(id);
213	  if (!task || !isFresh(task)) return;
214	
215	  if (!isTaskDegraded(task)) {
216	    alertedEpisodes.delete(task.id);
217	    return;
218	  }
219	  if (alertedEpisodes.has(task.id)) return;
220	
221	  const created = await createAlertReminder(task);
222	  alertedEpisodes.add(task.id);
223	  if (!created) return;
224	
225	  try {
226	    await sendSystemPush({
227	      title: `Job en échec : ${task.title}`,
228	      body: healthMessage(task),
229	      url: TASK_ALERT_HREF,
230	    });
231	  } catch (err) {
232	    // eslint-disable-next-line no-console
233	    console.warn('[taskAlerter] push échoué (non-fatal):', String(err));
234	  }
235	}
236	
237	/** Evaluate one task (serialized). Exported for tests. */
238	export function evaluateTaskAlert(id: string): Promise<void> {
239	  return enqueue(() => evaluateTask(id));
240	}
241	
242	/** Evaluate every registered task (serialized). Exported for tests; also the
243	 *  periodic sweep body. */
244	export function runTaskAlertSweep(): Promise<void> {
245	  return enqueue(async () => {
246	    const metas = await listTasks();
247	    for (const m of metas) await evaluateTask(m.id);
248	  });
249	}
250	
251	function onBusEvent(event: WorkstationEvent): void {
252	  if (event.type !== 'task-healthcheck' || !event.id) return;
253	  void evaluateTaskAlert(event.id);
254	}
255	
256	/**
257	 * Boot entry point (server/index.ts). Subscribes to the bus and starts the
258	 * periodic sweep (`sweepIntervalMs: 0` disables the timer — tests drive
259	 * `runTaskAlertSweep` directly). Returns a stop function. Calling start again
260	 * resets the in-memory state (fresh "boot").
261	 */
262	export function startTaskAlerter(opts: { sweepIntervalMs?: number } = {}): () => void {
263	  startedAtMs = Date.now();
264	  active = true;
265	  alertedEpisodes.clear();
266	  const unsubscribe = subscribe(onBusEvent);
267	  const sweepMs = opts.sweepIntervalMs ?? DEFAULT_SWEEP_MS;
268	  const timer = sweepMs > 0 ? setInterval(() => void runTaskAlertSweep(), sweepMs) : null;
269	  timer?.unref?.();
270	  return () => {
271	    active = false;
272	    unsubscribe();
273	    if (timer) clearInterval(timer);
274	  };
275	}
276	
277	/** Wait for every queued evaluation to settle — for tests. */
278	export function taskAlerterIdle(): Promise<void> {
279	  return queue;
280	}
281	
282	/* -------------------------------------------------------------------------- */
283	/*  Bell (GET /api/notifications)                                             */
284	/* -------------------------------------------------------------------------- */
285	
286	export interface TaskAlertNotification {
287	  id: string;
288	  title: string;
289	  context: string;
290	  project: { slug: string; name: string };
291	  href: string;
292	  kind: 'task-alert';
293	  updatedAt: string;
294	}
295	
296	/**
297	 * One bell entry per task CURRENTLY degraded (persisted health), independent
298	 * of the reminder's state: the reminder is the acknowledgment trail, this is
299	 * the live state (still shown after the reminder is marked done, until the job
300	 * is healthy again). The id embeds the pending alert reminder id when there is
301	 * one, so a NEW failure episode is a new id for the front's "already seen"
302	 * set (desktop notification fires again).
303	 */
304	export async function listTaskAlertNotifications(): Promise<TaskAlertNotification[]> {
305	  const metas: ExternalTaskMeta[] = await listTasks();
306	  const degraded = metas.filter(isTaskDegraded);
307	  if (degraded.length === 0) return [];
308	  const alerts = await pendingAlertsByTask().catch(() => new Map<string, string>());
309	  return degraded.map((m) => {
310	    const reminderId = alerts.get(m.id);
311	    return {
312	      id: `task-alert:${m.project.slug}:${m.id}${reminderId ? `:${reminderId}` : ''}`,
313	      title: `Job en échec : ${m.title}`,
314	      context: healthMessage(m),
315	      project: { slug: m.project.slug, name: m.project.name },
316	      href: TASK_ALERT_HREF,
317	      kind: 'task-alert',
318	      updatedAt: m.health.lastCheckedAt ?? m.updatedAt,
319	    };
320	  });
321	}
322

1	import fs from 'node:fs/promises';
2	import path from 'node:path';
3	
4	import {
5	  ExternalTaskSchema,
6	  type ExternalTask,
7	  type ExternalTaskMeta,
8	  type ExternalTaskSaveResult,
9	} from '../../src/types/task';
10	import { dataRoot, tasksDir } from '../config';
11	import { atomicWrite } from '../lib/atomicWrite';
12	import { isSafeSegment } from './slug';
13	
14	/**
15	 * File-backed store for External Tasks, copied from chipStore's patron:
16	 * `data/tasks/<slug>/<id>.json`, zod as the single source of truth, atomic
17	 * writes, optimistic locking on `updatedAt`, soft-delete to `<dataRoot>/trash/tasks`.
18	 *
19	 * This store does NOT publish on the event bus — like chips, the disk watcher
20	 * (taskWatcher.ts, via createTreeWatcher) is the ONLY publisher of
21	 * 'tasks-changed', so every write path (UI edit, seed, or a manager patch)
22	 * gets the same live-update behavior for free.
23	 */
24	
25	/* -------------------------------------------------------------------------- */
26	/*  Path resolution + guards                                                  */
27	/* -------------------------------------------------------------------------- */
28	
29	function taskPath(slug: string, id: string): string {
30	  if (!isSafeSegment(slug) || !isSafeSegment(id)) {
31	    throw new Error('Invalid slug or id');
32	  }
33	  return path.join(tasksDir(), slug, `${id}.json`);
34	}
35	
36	/**
37	 * A fresh `updatedAt` guaranteed STRICTLY LATER than `prevIso`. Two writes in
38	 * the same millisecond would otherwise stamp an identical `updatedAt`, which
39	 * silently defeats the optimistic lock (a stale save would match the on-disk
40	 * timestamp and slip through). Bumping to `prev + 1ms` when the wall clock has
41	 * not advanced keeps the lock reliable and preserves write ordering for the
42	 * watcher/UI.
43	 */
44	function nextUpdatedAt(prevIso: string): string {
45	  const prevMs = Date.parse(prevIso);
46	  const nowMs = Number.isNaN(prevMs) ? Date.now() : Math.max(Date.now(), prevMs + 1);
47	  return new Date(nowMs).toISOString();
48	}
49	
50	async function readTaskFile(filePath: string): Promise<ExternalTask | null> {
51	  let raw: string;
52	  try {
53	    raw = await fs.readFile(filePath, 'utf8');
54	  } catch {
55	    return null;
56	  }
57	  try {
58	    const parsed = JSON.parse(raw);
59	    const result = ExternalTaskSchema.safeParse(parsed);
60	    return result.success ? result.data : null;
61	  } catch {
62	    return null;
63	  }
64	}
65	
66	/** Every task under TASKS_DIR, optionally restricted to a single project slug. */
67	async function allTasks(slugFilter?: string): Promise<ExternalTask[]> {
68	  const base = tasksDir();
69	  let slugs: string[];
70	  try {
71	    const entries = await fs.readdir(base, { withFileTypes: true });
72	    slugs = entries.filter((d) => d.isDirectory()).map((d) => d.name);
73	  } catch {
74	    return [];
75	  }
76	  if (slugFilter) slugs = slugs.filter((s) => s === slugFilter);
77	
78	  const tasks: ExternalTask[] = [];
79	  await Promise.all(
80	    slugs.map(async (slug) => {
81	      let files: string[];
82	      try {
83	        files = (await fs.readdir(path.join(base, slug))).filter((f) => f.endsWith('.json'));
84	      } catch {
85	        return;
86	      }
87	      await Promise.all(
88	        files.map(async (file) => {
89	          const task = await readTaskFile(path.join(base, slug, file));
90	          if (task) tasks.push(task);
91	        }),
92	      );
93	    }),
94	  );
95	  return tasks;
96	}
97	
98	/** Locate a task by id across all project slugs (scan, like chipStore's
99	 *  findChipLocation). If a collision ever happens, the most recently updated
100	 *  match wins. */
101	async function findTaskLocation(id: string): Promise<{ slug: string; task: ExternalTask } | null> {
102	  if (!isSafeSegment(id)) return null;
103	  const base = tasksDir();
104	  let slugs: string[];
105	  try {
106	    const entries = await fs.readdir(base, { withFileTypes: true });
107	    slugs = entries.filter((d) => d.isDirectory()).map((d) => d.name);
108	  } catch {
109	    return null;
110	  }
111	
112	  const matches: { slug: string; task: ExternalTask }[] = [];
113	  await Promise.all(
114	    slugs.map(async (slug) => {
115	      const task = await readTaskFile(path.join(base, slug, `${id}.json`));
116	      if (task) matches.push({ slug, task });
117	    }),
118	  );
119	  if (matches.length === 0) return null;
120	  matches.sort((a, b) => b.task.updatedAt.localeCompare(a.task.updatedAt));
121	  return matches[0];
122	}
123	
124	/* -------------------------------------------------------------------------- */
125	/*  Metas                                                                     */
126	/* -------------------------------------------------------------------------- */
127	
128	function toMeta(t: ExternalTask): ExternalTaskMeta {
129	  return {
130	    id: t.id,
131	    project: t.project,
132	    title: t.title,
133	    kind: t.kind,
134	    status: t.status,
135	    health: t.health,
136	    lastRunAt: t.lastRunAt,
137	    lastRunSuccess: t.lastRunSuccess,
138	    createdAt: t.createdAt,
139	    updatedAt: t.updatedAt,
140	  };
141	}
142	
143	/** List task metas, optionally filtered to a project slug. Most recently
144	 *  updated first. */
145	export async function listTasks(filter?: { slug?: string }): Promise<ExternalTaskMeta[]> {
146	  const tasks = await allTasks(filter?.slug);
147	  const metas = tasks.map(toMeta);
148	  metas.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
149	  return metas;
150	}
151	
152	/* -------------------------------------------------------------------------- */
153	/*  Get one                                                                   */
154	/* -------------------------------------------------------------------------- */
155	
156	export async function getTask(slug: string, id: string): Promise<ExternalTask | null> {
157	  return readTaskFile(taskPath(slug, id));
158	}
159	
160	export async function findTask(id: string): Promise<ExternalTask | null> {
161	  const loc = await findTaskLocation(id);
162	  return loc ? loc.task : null;
163	}
164	
165	/** Same as findTask but also returns the resolved slug — routes need it to
166	 *  build the on-disk path for a mutation without re-scanning. */
167	export async function findTaskWithSlug(
168	  id: string,
169	): Promise<{ slug: string; task: ExternalTask } | null> {
170	  return findTaskLocation(id);
171	}
172	
173	/* -------------------------------------------------------------------------- */
174	/*  Create                                                                    */
175	/* -------------------------------------------------------------------------- */
176	
177	/** Create a task from a full, already-validated ExternalTask-shaped object.
178	 *  Never overwrites an existing file at the same path — the caller (route,
179	 *  or taskSeed's idempotent bootstrap) is expected to check existence first
180	 *  if "don't clobber" matters; this function itself always writes. */
181	export async function createTask(input: unknown): Promise<ExternalTaskSaveResult> {
182	  const parsed = ExternalTaskSchema.safeParse(input);
183	  if (!parsed.success) {
184	    return { ok: false, error: parsed.error.format() };
185	  }
186	  const task = parsed.data;
187	  const filePath = taskPath(task.project.slug, task.id);
188	  await atomicWrite(filePath, JSON.stringify(task, null, 2));
189	  const persisted = await readTaskFile(filePath);
190	  if (!persisted) return { ok: false, error: 'Failed to re-read persisted task' };
191	  return { ok: true, task: persisted };
192	}
193	
194	/** Whether a task file already exists at `<slug>/<id>.json` — used by
195	 *  taskSeed to stay idempotent (never overwrite an existing/edited task). */
196	export async function taskExists(slug: string, id: string): Promise<boolean> {
197	  try {
198	    await fs.access(taskPath(slug, id));
199	    return true;
200	  } catch {
201	    return false;
202	  }
203	}
204	
205	/* -------------------------------------------------------------------------- */
206	/*  Save (full edit — UI), optimistic lock                                    */
207	/* -------------------------------------------------------------------------- */
208	
209	export async function saveTask(
210	  slug: string,
211	  id: string,
212	  body: unknown,
213	): Promise<ExternalTaskSaveResult> {
214	  const parsed = ExternalTaskSchema.safeParse(body);
215	  if (!parsed.success) {
216	    return { ok: false, error: parsed.error.format() };
217	  }
218	
219	  const incoming = parsed.data;
220	  if (incoming.id !== id || incoming.project.slug !== slug) {
221	    return { ok: false, error: 'id/slug in body must match URL' };
222	  }
223	
224	  const filePath = taskPath(slug, id);
225	  const existing = await readTaskFile(filePath);
226	  if (!existing) {
227	    return { ok: false, error: 'Task not found' };
228	  }
229	  if (existing.updatedAt !== incoming.updatedAt) {
230	    return {
231	      ok: false,
232	      conflict: true,
233	      current: existing,
234	      error:
235	        'Le fichier a été modifié depuis son ouverture. Rechargez la page pour récupérer la dernière version.',
236	    };
237	  }
238	
239	  const now = nextUpdatedAt(existing.updatedAt);
240	  const next: ExternalTask = ExternalTaskSchema.parse({ ...incoming, updatedAt: now });
241	  await atomicWrite(filePath, JSON.stringify(next, null, 2));
242	
243	  const persisted = await readTaskFile(filePath);
244	  if (!persisted) return { ok: false, error: 'Failed to re-read persisted task' };
245	  return { ok: true, task: persisted };
246	}
247	
248	/* -------------------------------------------------------------------------- */
249	/*  Patch — used by taskManager for status/health/pid updates                 */
250	/* -------------------------------------------------------------------------- */
251	
252	/**
253	 * Read-fresh -> merge -> atomicWrite -> return the object exactly as
254	 * persisted. No optimistic lock here: these are system-driven updates
255	 * (start/stop/restart, healthcheck ticks), not a user edit racing another
256	 * user edit — the same "last write wins on a fresh read" semantics as
257	 * chipStore's mutateChip. Returns null if the task does not exist (including
258	 * "deleted concurrently").
259	 */
260	export async function patchTask(
261	  id: string,
262	  patch: Partial<ExternalTask>,
263	  opts?: { slug?: string },
264	): Promise<ExternalTask | null> {
265	  let slug = opts?.slug ?? (await findTaskLocation(id))?.slug;
266	  if (!slug) return null;
267	
268	  let filePath = taskPath(slug, id);
269	  let fresh = await readTaskFile(filePath);
270	  if (!fresh && opts?.slug) {
271	    // The caller's slug is the task's `project.slug`, which can differ from the
272	    // directory the file sits in (a hand-authored task): without this fallback
273	    // its health was never persisted, so its failures could never alert.
274	    slug = (await findTaskLocation(id))?.slug;
275	    if (!slug) return null;
276	    filePath = taskPath(slug, id);
277	    fresh = await readTaskFile(filePath);
278	  }
279	  if (!fresh) return null;
280	
281	  const now = nextUpdatedAt(fresh.updatedAt);
282	  const written = ExternalTaskSchema.parse({ ...fresh, ...patch, updatedAt: now });
283	  await atomicWrite(filePath, JSON.stringify(written, null, 2));
284	  return written;
285	}
286	
287	/* -------------------------------------------------------------------------- */
288	/*  Delete (soft, via trash)                                                  */
289	/* -------------------------------------------------------------------------- */
290	
291	/**
292	 * Soft-delete: the file is MOVED (never destroyed) to <dataRoot>/trash/tasks —
293	 * inside the ACTIVE data root, like `deleteConversation`, so a dev/test instance
294	 * (`WORKSTATION_DATA_ROOT`) never writes into the prod `data/trash`.
295	 */
296	export async function deleteTask(slug: string, id: string): Promise<boolean> {
297	  const filePath = taskPath(slug, id);
298	  try {
299	    await fs.access(filePath);
300	  } catch {
301	    return false;
302	  }
303	
304	  const trashPath = path.join(dataRoot(), 'trash', 'tasks', slug, `${id}-${Date.now()}.json`);
305	  await fs.mkdir(path.dirname(trashPath), { recursive: true });
306	  try {
307	    await fs.rename(filePath, trashPath);
308	  } catch {
309	    await fs.copyFile(filePath, trashPath);
310	    await fs.unlink(filePath);
311	  }
312	  return true;
313	}
