226	/* -------------------------------------------------------------------------- */
227	/*  Edit (remind update, MCP remind_update)                                   */
228	/* -------------------------------------------------------------------------- */
229	
230	/**
231	 * An edit to ONE reminder. Every field is optional; `dueAt: null` clears the
232	 * due date. `status: 'done'` is the same flip as `remind done`, `'pending'`
233	 * reopens a done reminder.
234	 */
235	export interface ReminderPatch {
236	  text?: string;
237	  dueAt?: string | null;
238	  priority?: ItemPriority;
239	  status?: 'pending' | 'done';
240	}
241	
242	/**
243	 * Pure: the item after `patch`. Text rewrites `body` and `prompt` together
244	 * (the convention of `buildReminderItem`); a done reminder that stays done
245	 * keeps its original `answeredAt`.
246	 */
247	export function applyReminderPatch(item: ReminderItem, patch: ReminderPatch, now: string): ReminderItem {
248	  const next: ReminderItem = { ...item };
249	  if (patch.text !== undefined) {
250	    const text = patch.text.trim();
251	    next.body = text;
252	    next.prompt = text;
253	  }
254	  if (patch.dueAt === null) delete next.dueAt;
255	  else if (patch.dueAt !== undefined) next.dueAt = new Date(patch.dueAt).toISOString();
256	  if (patch.priority !== undefined) next.priority = patch.priority;
257	  if (patch.status === 'done' && item.status !== 'answered') {
258	    next.status = 'answered';
259	    next.response = { done: true };
260	    next.answeredAt = now;
261	  } else if (patch.status === 'pending') {
262	    next.status = 'pending';
263	    delete next.response;
264	    delete next.answeredAt;
265	  }
266	  return next;
267	}
268	
269	/** Validation shared by the CLI and the MCP tool; returns an error message or null. */
270	export function reminderPatchError(patch: ReminderPatch): string | null {
271	  if (patch.text !== undefined && !patch.text.trim()) return 'le texte ne peut pas être vide';
272	  if (typeof patch.dueAt === 'string' && Number.isNaN(Date.parse(patch.dueAt))) {
273	    return `échéance invalide (date ISO attendue) : "${patch.dueAt}"`;
274	  }
275	  if (
276	    patch.text === undefined &&
277	    patch.dueAt === undefined &&
278	    patch.priority === undefined &&
279	    patch.status === undefined
280	  ) {
281	    return 'rien à modifier (texte, échéance, priorité ou statut attendu)';
282	  }
283	  return null;
284	}
285	
286	export type UpdateReminderResult =
287	  | { kind: 'not-found' }
288	  | { kind: 'invalid'; error: string }
289	  | { kind: 'unchanged'; item: ReminderItem }
290	  | { kind: 'updated'; item: ReminderItem }
291	  | { kind: 'error'; error: string };
292	
293	const UPDATE_MAX_ATTEMPTS = 3;
294	
295	/**
296	 * Edit ONE reminder — the single write path of `remind update` and the MCP
297	 * `remind_update` tool. The delta is re-checked by `isReminderEditOnlyFlip`
298	 * before the write (only that item, only editable fields, status limited to
299	 * the exact done/reopen shapes), then saved with the same bounded retry on
300	 * an optimistic-lock conflict as `remind_add`: each attempt re-reads the
301	 * evergreen conversation and re-applies the patch onto the fresh copy.
302	 */
303	export async function updateReminder(itemId: string, patch: ReminderPatch): Promise<UpdateReminderResult> {
304	  const invalid = reminderPatchError(patch);
305	  if (invalid) return { kind: 'invalid', error: invalid };
306	
307	  let lastConflict = 'raison inconnue';
308	  for (let attempt = 1; attempt <= UPDATE_MAX_ATTEMPTS; attempt++) {
309	    const found = await findReminderById(itemId);
310	    if (!found) return { kind: 'not-found' };
311	    const { conversation, item } = found;
312	
313	    const nextItem = applyReminderPatch(item, patch, new Date().toISOString());
314	    if (JSON.stringify(nextItem) === JSON.stringify(item)) return { kind: 'unchanged', item };
315	
316	    const nextConversation: Conversation = {
317	      ...conversation,
318	      items: conversation.items.map((it) => (it.id === itemId ? nextItem : it)),
319	    };
320	    if (!isReminderEditOnlyFlip(conversation, nextConversation)) {
321	      return {
322	        kind: 'error',
323	        error:
324	          "identity guard: le delta construit pour l'édition ne se limite pas aux champs " +
325	          'modifiables (texte, échéance, priorité, statut) d’un seul rappel — écriture refusée.',
326	      };
327	    }
328	
329	    const result = await saveConversation(REMINDERS_SLUG, REMINDERS_ID, nextConversation);
330	    if (result.ok) {
331	      const written = result.conversation.items.find(
332	        (it): it is ReminderItem => it.kind === 'reminder' && it.id === itemId,
333	      );
334	      return { kind: 'updated', item: written ?? nextItem };
335	    }
336	    if ('conflict' in result && result.conflict) {
337	      lastConflict = saveFailureReason(result);
338	      continue;
339	    }
340	    if ('secretBlocked' in result) {
341	      return { kind: 'error', error: 'le texte ressemble à une valeur de secret — un rappel ne doit jamais en contenir' };
342	    }
343	    return { kind: 'error', error: saveFailureReason(result) };
344	  }
345	  return { kind: 'error', error: `échec après ${UPDATE_MAX_ATTEMPTS} tentatives (conflit de verrou optimiste) — ${lastConflict}` };
346	}
