1	/**
2	 * Whether a SINGLE item, taken in isolation, is EXACTLY a reminder
3	 * `pending → answered` flip and nothing else. Factored out of
4	 * `isReminderDoneOnlyFlip` so each clause below is independently testable and
5	 * — per the lesson baked into this module's doctrine (a guard of the shape
6	 * `if (kind === X && optionalField)` is fail-OPEN the moment the optional
7	 * field is absent) — every check is written as an explicit STRICT equality
8	 * against the exact expected value, never an existence/truthiness check that
9	 * a missing field could silently satisfy.
10	 */
11	function isSingleReminderDoneFlip(prevItem: unknown, nextItem: unknown): boolean {
12	  if (
13	    prevItem === null ||
14	    nextItem === null ||
15	    typeof prevItem !== 'object' ||
16	    typeof nextItem !== 'object'
17	  ) {
18	    return false;
19	  }
20	  const p = prevItem as Record<string, unknown>;
21	  const n = nextItem as Record<string, unknown>;
22	
23	  // `kind` must be the literal 'reminder' on BOTH sides. Fail-closed: a
24	  // missing/undefined `kind`, or any value other than the exact literal,
25	  // rejects — there is no code path here where absence reads as a pass.
26	  if (p.kind !== 'reminder' || n.kind !== 'reminder') return false;
27	
28	  // `status` must flip EXACTLY 'pending' -> 'answered'. Any other pair
29	  // (unchanged, or a transition to/from anything else) is rejected.
30	  if (p.status !== 'pending' || n.status !== 'answered') return false;
31	
32	  // The previous item must not already carry a response — a done flip
33	  // originates from a genuinely pending reminder, never re-answers one.
34	  if (p.response !== undefined && p.response !== null) return false;
35	
36	  // `response` on the next item must be STRICTLY `{ done: true }` — exactly
37	  // one key, that key named `done`, that value `true`. An extra field, a
38	  // missing field, or `done: false` all reject.
39	  if (n.response === null || typeof n.response !== 'object' || Array.isArray(n.response)) {
40	    return false;
41	  }
42	  const responseKeys = Object.keys(n.response as Record<string, unknown>);
43	  if (responseKeys.length !== 1 || responseKeys[0] !== 'done') return false;
44	  if ((n.response as Record<string, unknown>).done !== true) return false;
45	
46	  // `answeredAt` must be newly ADDED by this flip: absent (or null) before,
47	  // a syntactically valid ISO datetime string after.
48	  if (p.answeredAt !== undefined && p.answeredAt !== null) return false;
49	  if (typeof n.answeredAt !== 'string' || Number.isNaN(Date.parse(n.answeredAt))) return false;
50	
51	  // Every other field on the item (id, kind, title, prompt, context, body,
52	  // dueAt, priority, comment, …) must be byte-identical — this flip touches
53	  // ONLY status/response/answeredAt.
54	  const pClone = { ...p };
55	  const nClone = { ...n };
56	  delete pClone.status;
57	  delete nClone.status;
58	  delete pClone.response;
59	  delete nClone.response;
60	  delete pClone.answeredAt;
61	  delete nClone.answeredAt;
62	  return JSON.stringify(pClone) === JSON.stringify(nClone);
63	}
64	
65	/**
66	 * The reminder-`done` counterpart of `isHandledOnlyFlip`: whether `next` is
67	 * `previous` with EXACTLY ONE `kind: 'reminder'` item flipped from
68	 * `pending` to `answered` (see `isSingleReminderDoneFlip` for the per-item
69	 * clauses) and nothing else in the conversation touched. Wired into
70	 * `remind done` (`server/cli/remind.ts`) as the write-path gate — the agent
71	 * CLI path is allowed to author exactly this one mutation on its own
72	 * evergreen `_reminders` conversation, and nothing broader.
73	 *
74	 * FAIL-CLOSED by construction: any shape that doesn't parse as
75	 * `{ items: [...] }` on both sides, any count of changed items other than
76	 * exactly one, or a changed item that isn't precisely the flip described
77	 * above, returns `false`. There is no path where malformed or unexpected
78	 * input is waved through.
79	 */
80	export function isReminderDoneOnlyFlip(previous: unknown, next: unknown): boolean {
81	  if (
82	    previous === null ||
83	    next === null ||
84	    typeof previous !== 'object' ||
85	    typeof next !== 'object'
86	  ) {
87	    return false;
88	  }
89	  const p = previous as Record<string, unknown>;
90	  const n = next as Record<string, unknown>;
91	
92	  const pItems = Array.isArray(p.items) ? p.items : null;
93	  const nItems = Array.isArray(n.items) ? n.items : null;
94	  if (!pItems || !nItems || pItems.length !== nItems.length) return false;
95	
96	  let changedIndex = -1;
97	  for (let i = 0; i < pItems.length; i++) {
98	    if (JSON.stringify(pItems[i]) === JSON.stringify(nItems[i])) continue;
99	    // A SECOND changed item means this is not a single-item flip — reject.
100	    if (changedIndex !== -1) return false;
101	    changedIndex = i;
102	  }
103	  // No item changed at all is not a done flip either.
104	  if (changedIndex === -1) return false;
105	  if (!isSingleReminderDoneFlip(pItems[changedIndex], nItems[changedIndex])) return false;
106	
107	  // Everything OTHER than `items` must stay byte-identical, except
108	  // `updatedAt` — the store stamps that mechanically on every save, exactly
109	  // like `isHandledOnlyFlip` exempts it above.
110	  const pClone = { ...p };
111	  const nClone = { ...n };
112	  delete pClone.items;
113	  delete nClone.items;
114	  delete pClone.updatedAt;
115	  delete nClone.updatedAt;
116	  return JSON.stringify(pClone) === JSON.stringify(nClone);
117	}
