196	/** Fields an agent-driven reminder EDIT (`remind update`, MCP `remind_update`) may change. */
197	const REMINDER_EDITABLE_FIELDS = ['body', 'prompt', 'dueAt', 'priority', 'status', 'response', 'answeredAt'] as const;
198	const REMINDER_PRIORITIES = ['low', 'normal', 'high', 'urgent'];
199	
200	/**
201	 * Whether a SINGLE `kind: 'reminder'` item differs from its previous version
202	 * ONLY by an edit an agent is allowed to author: text (`body`+`prompt`),
203	 * `dueAt` (set, changed or cleared), `priority`, and the done/reopen
204	 * transition. Same STRICT-equality discipline as `isSingleReminderDoneFlip`:
205	 * every field outside `REMINDER_EDITABLE_FIELDS` must be byte-identical, and
206	 * the status fields may only land on one of the two exact shapes `remind
207	 * done` / a restore produce — never an arbitrary `response`.
208	 */
209	function isSingleReminderEdit(prevItem: unknown, nextItem: unknown): boolean {
210	  if (
211	    prevItem === null ||
212	    nextItem === null ||
213	    typeof prevItem !== 'object' ||
214	    typeof nextItem !== 'object'
215	  ) {
216	    return false;
217	  }
218	  const p = prevItem as Record<string, unknown>;
219	  const n = nextItem as Record<string, unknown>;
220	
221	  if (p.kind !== 'reminder' || n.kind !== 'reminder') return false;
222	  if (p.id !== n.id || typeof p.id !== 'string') return false;
223	
224	  // Text: `body` stays a non-empty string (`prompt` is rewritten alongside it by `applyReminderPatch`).
225	  if (typeof n.body !== 'string' || n.body.trim() === '' || typeof n.prompt !== 'string') return false;
226	  // dueAt: absent or a parseable ISO datetime.
227	  if (n.dueAt !== undefined && (typeof n.dueAt !== 'string' || Number.isNaN(Date.parse(n.dueAt)))) return false;
228	  // priority: absent or one of the schema's literals.
229	  if (n.priority !== undefined && !REMINDER_PRIORITIES.includes(n.priority as string)) return false;
230	
231	  // Status: exactly the two shapes `remind done` and a restore produce.
232	  if (n.status === 'answered') {
233	    if (n.response === null || typeof n.response !== 'object' || Array.isArray(n.response)) return false;
234	    const keys = Object.keys(n.response as Record<string, unknown>);
235	    if (keys.length !== 1 || keys[0] !== 'done' || (n.response as Record<string, unknown>).done !== true) return false;
