255	  if (words.length === 0) return id;
256	  const [first, ...rest] = words;
257	  return [first.charAt(0).toUpperCase() + first.slice(1), ...rest].join(' ');
258	}
259	
260	function scheduleSummary(plist: PlistDict, kind: ExternalTaskKind, expected?: number): string {
261	  if (typeof plist.StartInterval === 'number') return `StartInterval ${plist.StartInterval} s`;
262	  if (plist.StartCalendarInterval !== undefined) {
263	    const n = calendarEntries(plist.StartCalendarInterval).length;
264	    return `StartCalendarInterval, ${n} créneau${n > 1 ? 'x' : ''}${
265	      expected !== undefined ? `, écart max ${expected} h` : ''
266	    }`;
267	  }
268	  if (kind === 'daemon') return 'KeepAlive (daemon)';
269	  return plist.RunAtLoad === true ? 'RunAtLoad seul (exécuté au chargement)' : 'à la demande';
270	}
