272	/**
273	 * Pure mapping plist → ExternalTask (no I/O). Returns null when the plist has
274	 * no valid `Label`. `file` is only used for the description.
275	 */
276	export function buildTaskFromPlist(plist: PlistDict, file: string, nowIso: string): ExternalTask | null {
277	  const label = plist.Label;
278	  if (typeof label !== 'string' || !LABEL_RE.test(label)) return null;
279	
280	  const id = label.slice(LABEL_PREFIX.length);
281	  const args = programArguments(plist);
282	  const command = displayCommand(args) || label;
283	  const workingDir =
284	    typeof plist.WorkingDirectory === 'string' && plist.WorkingDirectory
285	      ? plist.WorkingDirectory
286	      : cwdArgument(args);
287	  const logPaths = [plist.StandardOutPath, plist.StandardErrorPath].filter(
288	    (p, i, all): p is string => typeof p === 'string' && p.length > 0 && all.indexOf(p) === i,
289	  );
290	  // NAMES ONLY — the values never leave this expression.
291	  const env = plist.EnvironmentVariables;
292	  const envVarNames =
293	    env && typeof env === 'object' && !Array.isArray(env) ? Object.keys(env).filter((k) => k.length > 0) : [];
294	
295	  const kind = deriveKind(plist);
296	  const derivedIntervalHours = kind === 'scheduled' ? deriveExpectedIntervalHours(plist) : undefined;
297	  // Lateness is judged on LOG FRESHNESS (taskManager: last log mtime). Only a
298	  // job wrapped by run-with-markers.sh is guaranteed to write its logs on
299	  // every run (RUN START/END markers); a job that prints nothing (e.g.
300	  // me-ask-autoupdate, empty launchd.*.log) would read "EN RETARD" after one
301	  // interval although it ran fine — a false alert. So the interval is only
302	  // ENFORCED for marker-wrapped jobs; otherwise it is documented in the
303	  // description and failure detection relies on the exit code alone.
304	  const usesRunMarkers = args.some((a) => path.basename(a) === 'run-with-markers.sh');
305	  const expectedIntervalHours = usesRunMarkers ? derivedIntervalHours : undefined;
306	  const project = inferProject([workingDir ?? '', ...args, ...logPaths]) ?? {
307	    slug: 'launchd',
308	    name: 'launchd',
309	    path: launchAgentsDir(),
310	  };
311	
312	  return {
313	    schemaVersion: 1,
314	    id,
315	    project,
316	    title: titleFromId(id),
317	    description:
318	      `Découvert automatiquement depuis le plist ${path.basename(file)} (${path.dirname(file)}). ` +
319	      `Planification : ${scheduleSummary(plist, kind, derivedIntervalHours)}. ` +
320	      (derivedIntervalHours !== undefined && expectedIntervalHours === undefined
321	        ? 'Retard non surveillé : sans marqueurs run-with-markers.sh, la fraîcheur des logs ne prouve pas ' +
322	          `qu'un run a eu lieu — renseigner expectedIntervalHours (${derivedIntervalHours}) à la main si ` +
323	          'le job écrit dans ses logs à chaque run. '
324	        : '') +
325	      'Tâche éditable : la découverte ne réécrit jamais une tâche existante.',
326	    kind,
327	    launchdLabel: label,
328	    command,
329	    ...(workingDir ? { workingDir } : {}),
330	    logPaths,
331	    envVarNames,
332	    status: 'idle',
333	    healthCheckIntervalMs: 30000,
334	    autoRestart: kind === 'daemon',
335	    ...(expectedIntervalHours !== undefined ? { expectedIntervalHours } : {}),
336	    health: {},
337	    createdAt: nowIso,
338	    updatedAt: nowIso,
339	  };
340	}
