343	/*  Discovery                                                                 */
344	/* -------------------------------------------------------------------------- */
345	
346	export interface DiscoveryResult {
347	  created: string[];
348	  skipped: { label: string; reason: string }[];
349	  errors: { file: string; reason: string }[];
350	}
351	
352	async function registeredLabelsAndIds(): Promise<{ labels: Set<string>; ids: Set<string> }> {
353	  const metas = await listTasks();
354	  const labels = new Set<string>();
355	  const ids = new Set<string>();
356	  await Promise.all(
357	    metas.map(async (m) => {
358	      ids.add(m.id);
359	      // getTask by the task's own slug, falling back to an id scan (a task
360	      // file whose directory differs from `project.slug` is still counted).
361	      const task = (await getTask(m.project.slug, m.id)) ?? (await findTask(m.id));
362	      if (task) labels.add(task.launchdLabel);
363	    }),
364	  );
365	  return { labels, ids };
366	}
367	
368	/**
369	 * One discovery pass. Never throws for a single bad plist (recorded in
370	 * `errors`, logged by file name only); rejects only if the directory itself
371	 * cannot be read for a reason other than "absent" (absent = empty result).
372	 */
373	export async function discoverLaunchAgents(): Promise<DiscoveryResult> {
374	  const result: DiscoveryResult = { created: [], skipped: [], errors: [] };
375	  const dir = launchAgentsDir();
376	
377	  let names: string[];
378	  try {
379	    names = await fs.readdir(dir);
380	  } catch (err) {
381	    if ((err as NodeJS.ErrnoException)?.code === 'ENOENT') return result;
382	    throw err;
383	  }
384	  const candidates = names.filter((n) => n.startsWith(LABEL_PREFIX) && n.endsWith('.plist')).sort();
385	  if (candidates.length === 0) return result;
386	
387	  const { labels, ids } = await registeredLabelsAndIds();
388	
389	  for (const name of candidates) {
390	    const file = path.join(dir, name);
391	    try {
392	      const stat = await fs.stat(file);
393	      if (!stat.isFile()) continue;
394	    } catch {
395	      continue;
396	    }
397	
398	    const plist = await readPlist(file);
399	    if (!plist) {
400	      result.errors.push({ file: name, reason: 'plutil a échoué ou JSON invalide' });
401	      continue;
402	    }
403	    const label = typeof plist.Label === 'string' ? plist.Label : '';
404	    if (!LABEL_RE.test(label)) {
405	      result.skipped.push({ label: label || name, reason: 'label hors format com.elmabi.<kebab>' });
406	      continue;
407	    }
408	    if (labels.has(label)) {
409	      result.skipped.push({ label, reason: 'déjà enregistré' });
410	      continue;
411	    }
412	
413	    const task = buildTaskFromPlist(plist, file, new Date().toISOString());
414	    if (!task) continue;
415	    if (ids.has(task.id) || (await taskExists(task.project.slug, task.id))) {
416	      result.skipped.push({ label, reason: `id « ${task.id} » déjà utilisé` });
417	      continue;
418	    }
419	
420	    const saved = await createTask(task);
421	    if (!saved.ok) {
422	      result.errors.push({ file: name, reason: 'validation du schéma de tâche refusée' });
423	      continue;
424	    }
425	    labels.add(label);
426	    ids.add(task.id);
427	    result.created.push(task.id);
428	  }
429	  return result;
430	}
431	
432	/**
433	 * Boot + periodic discovery (default every 10 min, unref'd timer) so a newly
434	 * installed job shows up without a restart — the task store watcher then
435	 * emits `tasks-changed` and the UI updates live. Single-flight: a pass still
436	 * running when the timer fires is not doubled. Errors are logged, never
437	 * thrown. Returns a stop function.
438	 */
439	export function startLaunchAgentDiscovery(opts: { intervalMs?: number } = {}): () => void {
440	  const intervalMs = opts.intervalMs ?? DEFAULT_DISCOVERY_INTERVAL_MS;
441	  let running = false;
442	
443	  const run = async () => {
444	    if (running) return;
445	    running = true;
446	    try {
447	      const res = await discoverLaunchAgents();
448	      if (res.created.length > 0) {
449	        // eslint-disable-next-line no-console
450	        console.log(`[launchAgentDiscovery] tâches créées : ${res.created.join(', ')}`);
451	      }
452	      for (const e of res.errors) {
453	        // eslint-disable-next-line no-console
454	        console.warn(`[launchAgentDiscovery] ${e.file} ignoré : ${e.reason}`);
455	      }
456	    } catch (err) {
457	      // eslint-disable-next-line no-console
458	      console.warn('[launchAgentDiscovery] passe de découverte échouée (non-fatal):', String(err));
459	    } finally {
460	      running = false;
461	    }
462	  };
463	
464	  void run();
465	  const timer = intervalMs > 0 ? setInterval(() => void run(), intervalMs) : null;
466	  timer?.unref?.();
467	  return () => {
468	    if (timer) clearInterval(timer);
469	  };
470	}
