2	
3	/**
4	 * État React adossé à `localStorage` (préférence durable) ou `sessionStorage`
5	 * (confort de l'onglet courant).
6	 *
7	 * - Lecture UNE fois, dans l'initialiseur paresseux de `useState` : aucun
8	 *   effet, donc aucune dépendance à surveiller (`.claude/rules/react-effects.md`).
9	 * - Toute valeur relue passe par `parse`, qui DOIT valider et retomber sur un
10	 *   défaut : une valeur corrompue ou d'une ancienne version ne casse jamais le
11	 *   rendu.
12	 * - Chaque accès au storage est protégé par try/catch : navigation privée
13	 *   stricte, quota plein ou storage bloqué dégradent vers l'état en mémoire.
14	 *
15	 * `parse` et `serialize` doivent être des fonctions stables (niveau module) :
16	 * elles entrent dans les dépendances du setter.
17	 */
18	export type StoredStateArea = 'local' | 'session';
19	
20	export type StoredStateSetter<T> = (next: T | ((prev: T) => T)) => void;
21	
22	function storageFor(area: StoredStateArea): Storage | null {
23	  try {
24	    if (typeof window === 'undefined') return null;
25	    return area === 'local' ? window.localStorage : window.sessionStorage;
26	  } catch {
27	    return null;
28	  }
29	}
30	
31	export function readStoredRaw(area: StoredStateArea, key: string): string | null {
32	  try {
33	    return storageFor(area)?.getItem(key) ?? null;
34	  } catch {
35	    return null;
36	  }
37	}
38	
39	export function writeStoredRaw(area: StoredStateArea, key: string, value: string): void {
40	  try {
41	    storageFor(area)?.setItem(key, value);
42	  } catch {
43	    // Storage indisponible : l'état reste en mémoire pour cette visite.
44	  }
45	}
46	
47	export function useStoredState<T>(
48	  area: StoredStateArea,
49	  key: string,
50	  parse: (raw: string | null) => T,
51	  serialize: (value: T) => string,
52	): [T, StoredStateSetter<T>] {
53	  const [value, setValue] = useState<T>(() => parse(readStoredRaw(area, key)));
54	  // Miroir synchrone de la dernière valeur écrite : deux appels successifs
55	  // dans le même tick composent au lieu de repartir d'un `value` périmé.
56	  const latest = useRef(value);
57	
58	  const set = useCallback<StoredStateSetter<T>>(
59	    (next) => {
60	      const resolved =
61	        typeof next === 'function' ? (next as (prev: T) => T)(latest.current) : next;
62	      latest.current = resolved;
63	      setValue(resolved);
64	      writeStoredRaw(area, key, serialize(resolved));
65	    },
66	    [area, key, serialize],
67	  );
68	
69	  return [value, set];
70	}
