};

function isDegraded(task: ExternalTaskMeta): boolean {
  if (task.kind === 'scheduled') {
    return task.health.late === true || task.lastRunSuccess === false;
  }
  return task.status === 'failed' || task.status === 'unhealthy' || task.status === 'stopped';
}

function formatHealthAge(minutes: number, language: string): string {
  const formatter = new Intl.RelativeTimeFormat(language, { numeric: 'auto' });
  if (minutes < 60) return formatter.format(-minutes, 'minute');
  const hours = Math.round(minutes / 60);
  if (hours < 48) return formatter.format(-hours, 'hour');
  return formatter.format(-Math.round(hours / 24), 'day');
}

