120	        next.status = 'answered';
121	        next.response = { done: true };
122	        next.answeredAt = nowIso;
123	      }
124	    } else if (current.status === 'answered') {
125	      next.status = 'pending';
126	      delete next.response;
127	      delete next.answeredAt;
128	    }
129	  }
