137	 * l'appelant abandonne alors l'écriture au lieu de ressusciter l'item.
138	 */
139	export function patchReminderInItems(
140	  items: Item[],
141	  original: ReminderItem,
142	  draft: ReminderDraft,
143	  nowIso: string,
144	): Item[] | null {
145	  let found = false;
146	  const next = items.map((entry) => {
147	    if (entry.id !== original.id || entry.kind !== 'reminder') return entry;
148	    found = true;
149	    return applyReminderDraft(entry, original, draft, nowIso);
150	  });
151	  return found ? next : null;
152	}
