import { useCallback, useEffect, useId, useMemo, useState } from 'react';
import { Bell, Check, AlertTriangle, ChevronDown, ChevronRight, X, Search, LayoutGrid, List, ChevronUp, Rows, ClipboardCopy, Pencil, RotateCcw } from 'lucide-react';
import type { Conversation, Item, ReminderItem } from '../types/conversation';
import { ReminderDueInput, ReminderEditor, ReminderPrioritySegmented } from './reminders/ReminderEditor';
import { patchReminderInItems, type ReminderDraft } from './reminders/reminderEdit';
import { ApiError, getConversation, mutateConversationWithRetry } from '../lib/api';
import { useServerEvents } from '../hooks/useServerEvents';
import { Button } from './ui/Button';
import { Input } from './ui/Input';
import { useHoverCard } from '../hooks/useHoverCard';
import { ReminderHoverCardPortal } from './ReminderHoverCardPortal';
import { useTranslation } from 'react-i18next';
import { RuntimeBadge } from './origin/RuntimeBadge';
import { OriginLine } from './origin/OriginLine';
import { useAgentSessions } from './origin/useAgentSessions';
import type { AgentSessionSummary } from '../types/agentSession';

const REMINDERS_SLUG = '_reminders';
const REMINDERS_ID = 'rappels';
const DEFAULT_VISIBLE_COUNT = 5;

/**
 * Plafond DOM sur la liste ARCHIVE (rappels `answered`) — même idiome que
 * `FILE_LIST_DOM_CAP` (`src/components/git/GitDetailPanel.tsx`) et le
 * `LIST_CAP = 12` déjà appliqué au champ `reminders` de `hubPulse.ts` pour un
 * autre consommateur (le pouls du hub). `_reminders/rappels` n'a aucune
 * purge côté store : les rappels `answered` s'y accumulent indéfiniment, donc
 * sans plafond ce sont potentiellement des milliers de `<li>` React. La liste
 * PENDING n'a pas ce plafond — bornée par un volume humain réaliste de
 * rappels en attente, contrairement à l'archive qui ne fait que croître.
 * Jamais un plafond silencieux : le « + N autres » ci-dessous est dérivé du
 * VRAI total (`completed.length`), pas de la longueur de la liste affichée.
 */
const REMINDER_ARCHIVE_DOM_CAP = 50;

function newItemId(): string {
  return `reminder-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

/**
 * Badge mono discret : ID du rappel + affordance « copier » — indispensable
 * pour qu'un agent puisse traiter un rappel PAR ID (`bun run remind read
 * <id>` / `remind done <id>`) sans deviner. Même style que le pied de page
 * ID de `ChipHoverCardPortal` (mono, ink-faint, accent au survol du bouton).
 */
function ReminderIdTag({ id, className = '' }: { id: string; className?: string }) {
  const { t } = useTranslation();
  const [copied, setCopied] = useState(false);

  const handleCopy = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    void navigator.clipboard.writeText(id).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  return (
    <span
      className={`glass-badge inline-flex items-center gap-1 rounded border border-line-soft/60 bg-paper-deep/30 px-1.5 py-0.5 font-mono text-[0.625rem] text-ink-faint ${className}`}
    >
      <span className="truncate max-w-[160px]" title={id}>
        {id}
      </span>
      <button data-shape="icon"
        type="button"
        onClick={handleCopy}
        className="glass-control shrink-0 rounded p-0.5 text-ink-faint hover:text-accent hover:bg-paper-card transition-colors cursor-pointer"
        title={t('reminders.copyIdTitle', "Copier l'ID du rappel")}
      >
        {copied ? (
          <Check className="h-2.5 w-2.5 text-status-done" />
        ) : (
          <ClipboardCopy className="h-2.5 w-2.5" />
        )}
      </button>
    </span>
  );
}

