1	/**
2	 * État persistant de la barre d'outils « Démons & jobs » (ExternalTaskPanel) —
3	 * logique PURE, testable sans DOM. Le hook `useStoredState` s'occupe du
4	 * storage ; ce module ne fait que valider / sérialiser / transformer.
5	 *
6	 * Choix de persistance :
7	 * - mode de regroupement et filtre d'état → `localStorage` (préférences
8	 *   durables : on revient sur la page, on retrouve sa vue) ;
9	 * - repli des groupes → `localStorage`, sous la forme d'une INTENTION par
10	 *   défaut (dernier « Tout replier / Tout déplier ») + la liste des groupes qui
11	 *   y font exception. Un groupe qui apparaît plus tard suit donc la dernière
12	 *   intention globale de l'utilisateur au lieu de s'ouvrir d'office ;
13	 * - texte de recherche → `sessionStorage` seulement : il survit à un aller-
14	 *   retour dans l'onglet, mais pas au lendemain. Sur un panneau de
15	 *   supervision, une recherche oubliée pendant des jours masquerait un démon
16	 *   dégradé ; le bandeau de synthèse compte toujours TOUTES les alertes.
17	 */
18	
19	export const TASK_STATUS_FILTERS = ['all', 'degraded', 'daemon', 'scheduled'] as const;
20	export type TaskStatusFilter = (typeof TASK_STATUS_FILTERS)[number];
21	
22	export const TASK_GROUP_MODES = ['project', 'kind', 'flat'] as const;
23	export type TaskGroupMode = (typeof TASK_GROUP_MODES)[number];
24	
25	export const TASK_TOOLBAR_STORAGE_KEYS = {
26	  /** Clé historique, conservée telle quelle pour ne pas perdre le choix déjà enregistré. */
27	  groupMode: 'external-tasks-group-mode',
28	  statusFilter: 'external-tasks-status-filter',
29	  collapse: 'external-tasks-collapse',
30	  search: 'external-tasks-search',
31	} as const;
32	
33	/** Plafond de la liste d'exceptions de repli (le storage ne grossit jamais sans borne). */
34	export const MAX_COLLAPSE_EXCEPTIONS = 200;
35	/** Longueur maximale d'une clé de groupe ou d'une recherche relue. */
36	const MAX_KEY_LENGTH = 200;
37	export const MAX_SEARCH_LENGTH = 200;
38	
39	export function parseGroupMode(raw: string | null): TaskGroupMode {
40	  return (TASK_GROUP_MODES as readonly string[]).includes(raw ?? '')
41	    ? (raw as TaskGroupMode)
42	    : 'project';
43	}
44	
45	export function parseStatusFilter(raw: string | null): TaskStatusFilter {
46	  return (TASK_STATUS_FILTERS as readonly string[]).includes(raw ?? '')
47	    ? (raw as TaskStatusFilter)
48	    : 'all';
49	}
50	
51	export function serializeString(value: string): string {
52	  return value;
53	}
54	
55	export function parseSearch(raw: string | null): string {
56	  if (typeof raw !== 'string') return '';
57	  return raw.slice(0, MAX_SEARCH_LENGTH);
58	}
59	
60	/* -------------------------------------------------------------------------- */
61	/*  Repli des groupes                                                         */
62	/* -------------------------------------------------------------------------- */
63	
64	export interface CollapseState {
65	  /** Intention globale : dernier « Tout replier » (true) ou « Tout déplier » (false). */
66	  defaultCollapsed: boolean;
67	  /** Groupes dont l'état diffère de l'intention globale (ordre = ancienneté). */
68	  exceptions: string[];
69	}
70	
71	export const INITIAL_COLLAPSE_STATE: CollapseState = { defaultCollapsed: false, exceptions: [] };
72	
73	function capExceptions(keys: string[]): string[] {
74	  return keys.length > MAX_COLLAPSE_EXCEPTIONS
75	    ? keys.slice(keys.length - MAX_COLLAPSE_EXCEPTIONS)
76	    : keys;
77	}
78	
79	export function parseCollapseState(raw: string | null): CollapseState {
80	  if (!raw) return INITIAL_COLLAPSE_STATE;
81	  let parsed: unknown;
82	  try {
83	    parsed = JSON.parse(raw);
84	  } catch {
85	    return INITIAL_COLLAPSE_STATE;
86	  }
87	  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return INITIAL_COLLAPSE_STATE;
88	  const record = parsed as Record<string, unknown>;
89	  if (record.v !== 1 || typeof record.defaultCollapsed !== 'boolean') return INITIAL_COLLAPSE_STATE;
90	  const rawExceptions = Array.isArray(record.exceptions) ? record.exceptions : [];
91	  const seen = new Set<string>();
92	  const exceptions: string[] = [];
93	  for (const entry of rawExceptions) {
94	    if (typeof entry !== 'string' || entry.length === 0 || entry.length > MAX_KEY_LENGTH) continue;
95	    if (seen.has(entry)) continue;
96	    seen.add(entry);
97	    exceptions.push(entry);
98	  }
99	  return { defaultCollapsed: record.defaultCollapsed, exceptions: capExceptions(exceptions) };
100	}
101	
102	export function serializeCollapseState(state: CollapseState): string {
103	  return JSON.stringify({ v: 1, defaultCollapsed: state.defaultCollapsed, exceptions: state.exceptions });
104	}
105	
106	export function isGroupCollapsed(state: CollapseState, key: string): boolean {
107	  return state.exceptions.includes(key) ? !state.defaultCollapsed : state.defaultCollapsed;
108	}
109	
110	export function toggleGroupCollapsed(state: CollapseState, key: string): CollapseState {
111	  const exceptions = state.exceptions.includes(key)
112	    ? state.exceptions.filter((entry) => entry !== key)
113	    : capExceptions([...state.exceptions, key]);
114	  return { defaultCollapsed: state.defaultCollapsed, exceptions };
115	}
116	
117	/** « Tout replier » / « Tout déplier » : nouvelle intention globale, exceptions remises à zéro. */
118	export function setAllGroupsCollapsed(collapsed: boolean): CollapseState {
119	  return { defaultCollapsed: collapsed, exceptions: [] };
120	}
121	
122	/**
123	 * Libellé du bouton global pour les groupes VISIBLES : s'il en reste au moins
124	 * un ouvert, l'action proposée est « Tout replier », sinon « Tout déplier ».
125	 */
126	export function nextToggleAllAction(state: CollapseState, visibleKeys: string[]): 'collapse' | 'expand' {
127	  return visibleKeys.some((key) => !isGroupCollapsed(state, key)) ? 'collapse' : 'expand';
128	}
129	
130	/** Clé stable d'un groupe, indépendante de la langue d'affichage. */
131	export function taskGroupKey(mode: Exclude<TaskGroupMode, 'flat'>, id: string): string {
132	  return `${mode}:${id}`;
133	}
